"""Parse a number to an integer if possible"""
def parse_int(val: Any, name: Any) -> object {
    if (val is None) {
        return val;
    }
    try {
        return int(val);
    } except ValueError {
        raise ValueError(f"Please provide a number for {name}, instead of {val}");
    }
}

